48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        String normalizedAddress = normalizeAddress(owner.getAddress());
108	        if (normalizedAddress.isEmpty()) {
109	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
110	                "Address must not be blank after normalization");
111	        }
112	        owner.setAddress(normalizedAddress);
113	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
117	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
118	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
119	        owner.setRegistrationDate(businessDate);
120	        long createdToday = this.clinicService.findAllOwners().stream()
121	            .map(Owner::getRegistrationDate)
122	            .filter(businessDate::equals)
123	            .count();
124	        if (createdToday >= 100) {
125	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
126	                "The maximum number of owners for today has already been reached");
127	        }
128	        owner.setBulkSignupWarning(createdToday > 80);
129	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
130	            .map(Owner::getTelephone)
131	            .filter(java.util.Objects::nonNull)
132	            .anyMatch(normalizedTelephone::equals);
133	        if (telephoneInUse) {
134	            throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                "An owner with this telephone number already exists");
136	        }
137	        String normalizedEmail = owner.getEmail();
138	        if (normalizedEmail != null) {
139	            boolean emailInUse = this.clinicService.findAllOwners().stream()
140	                .map(Owner::getEmail)
141	                .filter(java.util.Objects::nonNull)
142	                .map(existing -> existing.toLowerCase(java.util.Locale.ROOT))
143	                .anyMatch(normalizedEmail::equals);
144	            if (emailInUse) {
145	                throw new ResponseStatusException(HttpStatus.CONFLICT,
146	                    "An owner with this email address already exists");
147	            }
148	        }
149	        String lastNameKey = normalizeForHousehold(owner.getLastName());
150	        String addressKey = normalizeForHousehold(owner.getAddress());
151	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
152	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
153	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
154	            .toList();
155	        if (!householdMembers.isEmpty()) {
156	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
157	                throw new ResponseStatusException(HttpStatus.CONFLICT,
158	                    "An owner with this last name already exists at this address");
159	            }
160	            String householdId = householdId(lastNameKey, addressKey);
161	            owner.setHouseholdId(householdId);
162	            for (Owner member : householdMembers) {
163	                if (!householdId.equals(member.getHouseholdId())) {
164	                    member.setHouseholdId(householdId);
165	                    this.clinicService.saveOwner(member);
166	                }
167	            }
168	        }
169	        String cityKey = normalizeForHousehold(owner.getCity());
170	        long cityCount = this.clinicService.findAllOwners().stream()
171	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
172	            .count();
173	        if (cityCount >= 50) {
174	            throw new ResponseStatusException(HttpStatus.CONFLICT,
175	                "This city already has the maximum number of owners");
176	        }
177	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
178	        owner.setHouseholdSize(householdMembers.size() + 1);
179	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
183	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
184	        headers.setLocation(UriComponentsBuilder.newInstance()
185	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
186	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    /**
190	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
191	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
192	     * to the effective registration date (whether supplied in the request or defaulted to the server
193	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
194	     * business day.
195	     *
196	     * @param date the effective registration date
197	     * @return the same date if it is a weekday, otherwise the following Monday
198	     */
199	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
200	        return switch (date.getDayOfWeek()) {
201	            case SATURDAY -> date.plusDays(2);
202	            case SUNDAY -> date.plusDays(1);
203	            default -> date;
204	        };
205	    }
206	
207	    /**
208	     * Counts the owners that already exist (before the current create) whose first and last names
209	     * both match the supplied names, compared case-insensitively. The returned value is captured on
210	     * the new owner at creation time and does not change as further owners are added later.
211	     *
212	     * @param firstName the new owner's first name
213	     * @param lastName  the new owner's last name
214	     * @return the number of pre-existing namesake owners
215	     */
216	    private int namesakeCount(String firstName, String lastName) {
217	        return (int) this.clinicService.findAllOwners().stream()
218	            .filter(existing -> existing.getFirstName() != null
219	                && existing.getFirstName().equalsIgnoreCase(firstName)
220	                && existing.getLastName() != null
221	                && existing.getLastName().equalsIgnoreCase(lastName))
222	            .count();
223	    }
224	
225	    /**
226	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
227	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
228	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
229	     * zero-padded sequence equal to one more than the number of owners already in that city
230	     * (e.g. {@code 'SYD-SMI-0007'}).
231	     *
232	     * @param city     the owner's city
233	     * @param lastName the owner's last name
234	     * @return the assigned customer code
235	     */
236	    private String nextCustomerCode(String city, String lastName) {
237	        String cityPrefix = first3Upper(city);
238	        String lastPrefix = first3Upper(lastName);
239	        String cityKey = normalizeForHousehold(city);
240	        long sequence = this.clinicService.findAllOwners().stream()
241	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
242	            .count() + 1L;
243	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
244	    }
245	
246	    /**
247	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
248	     * shorter. A {@code null} value yields the empty string.
249	     *
250	     * @param value the source value
251	     * @return the upper-cased first three characters
252	     */
253	    private String first3Upper(String value) {
254	        String v = (value == null ? "" : value);
255	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
256	    }
257	
258	    /**
259	     * Normalizes a street address applied whenever an owner is created: leading and trailing
260	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
261	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
262	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
263	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
264	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
265	     * {@code '12 MAIN STREET'}.
266	     *
267	     * @param address the raw address as submitted, or {@code null} when absent
268	     * @return the normalized address, or the empty string when the value is blank
269	     */
270	    private String normalizeAddress(String address) {
271	        String collapsed = (address == null ? "" : address)
272	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
273	        if (collapsed.isEmpty()) {
274	            return "";
275	        }
276	        String[] tokens = collapsed.split(" ");
277	        for (int i = 0; i < tokens.length; i++) {
278	            switch (tokens[i]) {
279	                case "ST" -> tokens[i] = "STREET";
280	                case "RD" -> tokens[i] = "ROAD";
281	                case "AVE" -> tokens[i] = "AVENUE";
282	                default -> { }
283	            }
284	        }
285	        return String.join(" ", tokens);
286	    }
287	
288	    /**
289	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
290	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
291	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
292	     * empty string.
293	     *
294	     * @param value the raw value (last name or address) as submitted
295	     * @return the normalized comparison key
296	     */
297	    private String normalizeForHousehold(String value) {
298	        if (value == null) {
299	            return "";
300	        }
301	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
302	    }
303	
304	    /**
305	     * Derives the stable shared household identifier for a household, keyed on the normalized last
306	     * name and address. Because it is a pure function of those normalized keys, every owner in the
307	     * same household deterministically computes the same value. The identifier is the first 12
308	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
309	     * (the separator prevents distinct name/address pairs from colliding).
310	     *
311	     * @param lastNameKey the normalized last-name comparison key
312	     * @param addressKey  the normalized address comparison key
313	     * @return the stable household identifier
314	     */
315	    private String householdId(String lastNameKey, String addressKey) {
316	        String seed = lastNameKey + "�" + addressKey;
317	        try {
318	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
319	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
320	            StringBuilder sb = new StringBuilder(digest.length * 2);
321	            for (byte b : digest) {
322	                sb.append(String.format("%02x", b));
323	            }
324	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
325	        }
326	        catch (java.security.NoSuchAlgorithmException e) {
327	            throw new IllegalStateException("SHA-256 not available", e);
328	        }
329	    }
330	
331	    /**
332	     * The exact number of national (subscriber) digits required for a given country calling code,
333	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
334	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
335	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
336	     */
337	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
338	        java.util.Map.of("61", 9, "1", 10);
339	
340	    /**
341	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
342	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
343	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
344	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
345	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
346	     * is stored as {@code '+61412345678'}.
347	     *
348	     * <p>In addition, when the number's country code has a fixed national-number length (see
349	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
350	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
351	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
352	     *
353	     * @param telephone the raw telephone number as submitted
354	     * @return the normalized E.164 telephone number
355	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
356	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
357	     *         for its country code
358	     */
359	    private String normalizeTelephone(String telephone) {
360	        String raw = telephone == null ? "" : telephone.trim();
361	        String digits = raw.replaceAll("\\D", "");
362	        String e164;
363	        if (raw.startsWith("+")) {
364	            e164 = "+" + digits;
365	        } else {
366	            if (digits.startsWith("0")) {
367	                digits = digits.substring(1);
368	            }
369	            e164 = "+61" + digits;
370	        }
371	        int digitCount = e164.length() - 1;
372	        if (digitCount < 8 || digitCount > 15) {
373	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
374	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
375	        }
376	        validateNationalNumberLength(e164);
377	        return e164;
378	    }
379	
380	    /**
381	     * Validates that an E.164 number's national-number length is correct for its country code.
382	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
383	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
384	     * following it must match exactly. Country codes without a fixed length are left unchecked.
385	     *
386	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
387	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
388	     *         for the country code
389	     */
390	    private void validateNationalNumberLength(String e164) {
391	        String allDigits = e164.substring(1);
392	        String bestCode = null;
393	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
394	            if (allDigits.startsWith(code)
395	                    && (bestCode == null || code.length() > bestCode.length())) {
396	                bestCode = code;
397	            }
398	        }
399	        if (bestCode == null) {
400	            return;
401	        }
402	        int nationalLength = allDigits.length() - bestCode.length();
403	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
404	        if (nationalLength != required) {
405	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
406	                "Telephone for country code '+" + bestCode + "' must have " + required
407	                    + " national digits");
408	        }
409	    }
410	
411	    /**
412	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
413	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
414	     * (absent) or already valid.
415	     *
416	     * @param email the email address as submitted, or {@code null} when absent
417	     * @return the lower-cased email, or {@code null} when absent
418	     */
419	    private String normalizeEmail(String email) {
420	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
421	    }
422	
423	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
424	    @Override
425	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
426	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
427	        if (currentOwner == null) {
428	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
429	        }
430	        currentOwner.setAddress(ownerFieldsDto.getAddress());
431	        currentOwner.setCity(ownerFieldsDto.getCity());
432	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
433	        currentOwner.setLastName(ownerFieldsDto.getLastName());
434	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
435	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
436	        this.clinicService.saveOwner(currentOwner);
437	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
438	    }
439	
440	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
441	    @Transactional
442	    @Override
443	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
444	        Owner owner = this.clinicService.findOwnerById(ownerId);
445	        if (owner == null) {
446	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
447	        }
448	        this.clinicService.deleteOwner(owner);
449	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
450	    }
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
455	        Owner owner = this.clinicService.findOwnerById(ownerId);
456	        if (owner == null) {
457	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
458	        }
459	        HttpHeaders headers = new HttpHeaders();
460	        Pet pet = petMapper.toPet(petFieldsDto);
461	        owner.setId(ownerId);
462	        pet.setOwner(owner);
463	        pet.getType().setName(null);
464	        this.clinicService.savePet(pet);
465	        PetDto petDto = petMapper.toPetDto(pet);
466	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
467	            .buildAndExpand(pet.getId()).toUri());
468	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
469	    }
470	
471	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
472	    @Override
473	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
474	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
475	        if (currentOwner != null) {
476	            Pet currentPet = this.clinicService.findPetById(petId);
477	            if (currentPet != null) {
478	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
479	                currentPet.setName(petFieldsDto.getName());
480	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
481	                this.clinicService.savePet(currentPet);
482	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
483	            }
